const repositoryProjects = `-- name: RepositoryProjects :many
SELECT p.id, p.key, p.name, p.description, p.lead_id, p.template, p.open_role_id, p.issue_counter, p.archived_at, p.created_at, p.updated_at, p.risks_decisions FROM projects p JOIN project_repositories pr ON pr.project_id = p.id WHERE pr.repository_id = $1
`

// Projects connected to a repository: only their keys are linked from Git activity.
func (q *Queries) RepositoryProjects(ctx context.Context, repositoryID uuid.UUID) ([]Project, error) {
	rows, err := q.db.Query(ctx, repositoryProjects, repositoryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Project{}
	for rows.Next() {
		var i Project
		if err := rows.Scan(
			&i.ID,
			&i.Key,
			&i.Name,
			&i.Description,
			&i.LeadID,
			&i.Template,
			&i.OpenRoleID,
			&i.IssueCounter,
			&i.ArchivedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RisksDecisions,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

